import * as T from './three.module.js';
let renderer,scene,camera,ship,stars,orbit,clock=0,last=0,container;
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
try{renderer=new T.WebGLRenderer({alpha:true,antialias:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));scene=new T.Scene();camera=new T.PerspectiveCamera(37,1,.1,100);camera.position.set(4,3.3,6);camera.lookAt(0,0,0);scene.add(new T.HemisphereLight(0xa5f2ff,0x363264,3));const light=new T.DirectionalLight(0xffffff,3);light.position.set(3,5,4);scene.add(light);ship=new T.Group();scene.add(ship);
const m=c=>new T.MeshStandardMaterial({color:c,roughness:.45,metalness:.35});function box(x,y,z,c,px,py,pz){const b=new T.Mesh(new T.BoxGeometry(x,y,z),m(c));b.position.set(px,py,pz);ship.add(b);return b;}
box(.85,.72,.72,0xdceaf5,0,0,0);box(.66,.48,.035,0x172e50,0,0,.38);for(let x of [-1,1]){box(1.15,.045,1.3,0x316ed0,x*1.05,0,0);box(.4,.08,.08,0xa6c6e0,x*.54,0,0);for(let a=0;a<4;a++)box(.016,.01,1.26,0x80b6e7,x*1.05-.45+a*.3,.028,0);for(let a=0;a<4;a++)box(1.1,.01,.015,0x80b6e7,x*1.05,.028,-.47+a*.31);}
let dish=new T.Mesh(new T.SphereGeometry(.5,32,16,0,Math.PI*2,0,.9),new T.MeshStandardMaterial({color:0xe5edf7,side:T.DoubleSide,roughness:.4,metalness:.5}));dish.position.set(0,.14,0);ship.add(dish);box(.035,.75,.035,0xe5d7b9,0,.8,0);const tip=new T.Mesh(new T.SphereGeometry(.065,16,12),new T.MeshBasicMaterial({color:0x9dffe7}));tip.position.set(0,1.2,0);ship.add(tip);
const planet=new T.Mesh(new T.SphereGeometry(2.9,40,24),m(0x236e86));planet.position.set(0,-4.7,-1.5);scene.add(planet);const atmosphere=new T.Mesh(new T.SphereGeometry(3.03,40,24),new T.MeshBasicMaterial({color:0x58d8ee,transparent:true,opacity:.1,side:T.BackSide}));atmosphere.position.copy(planet.position);scene.add(atmosphere);
orbit=new T.Group();scene.add(orbit);for(let i=0;i<3;i++){const ring=new T.Mesh(new T.TorusGeometry(2+i*.48,.006,6,100),new T.MeshBasicMaterial({color:0x79d7dd,transparent:true,opacity:.18-i*.04}));ring.rotation.x=Math.PI/2+.2;ring.position.y=-.7;orbit.add(ring);}
const positions=[];for(let i=0;i<100;i++)positions.push((Math.random()-.5)*18,(Math.random()-.5)*15,(Math.random()-.5)*12-4);const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(positions,3));stars=new T.Points(geo,new T.PointsMaterial({color:0xc0dcff,size:.024}));scene.add(stars);
function mount(){container=document.getElementById('space-view');if(container){container.replaceChildren(renderer.domElement);resize();renderOnce();}}function resize(){if(!container?.isConnected)return;const r=container.getBoundingClientRect();renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();}function renderOnce(){renderer.render(scene,camera);}function frame(t){requestAnimationFrame(frame);if(document.hidden||!container?.isConnected||reduced)return;if(t-last<33)return;const dt=Math.min((t-last)/1000,.1);last=t;clock+=dt;ship.rotation.y=.2+Math.sin(clock*.4)*.3;ship.rotation.z=Math.sin(clock*.55)*.09;ship.position.y=Math.sin(clock*.8)*.12;stars.rotation.y=clock*.008;orbit.rotation.y=clock*.035;renderOnce();}addEventListener('space-mount',mount);addEventListener('resize',resize);mount();requestAnimationFrame(frame);
}catch(e){/* The full question game also works without WebGL. */}
